  "help.body": "Crewboard — планы и запуски воркеров\n\nПлан\n  {prog} init [--goal \"цель\"]\n  {prog} plan list | new <id> --goal \"…\" | split <id> --from <план> --goal \"…\" --tasks a,b,c\n               | use <id> | archive <id> | unarchive <id> | rename <id> --goal \"…\"\n  {prog} chat unbind <план>\n                                           несколько планов в репозитории; команды работают с текущим, --plan <id> — с другим\n  {prog} status [--json] [--plan id]\n  {prog} wait [--for decision|finished|check|any] [--tasks a,b] [--plan id] [--interval 15s] [--timeout 30m] [--json]\n                                           оркестратору: запустите в фоне; выход 0 — решение, конец запуска или шаг проверки, 2 — таймаут, 1 — ошибка\n                                           ждёт следующего изменения; с --tasks, если все задачи уже там (закончены, проверены,\n                                           решены или закрыты), сразу выход 0 и строки с пометкой «уже»; по умолчанию --timeout 30m\n  {prog} task add <id> --title \"…\" [--kind implement|review|research|decision|root] [--lane \"…\"]\n                [--deps a,b] [--worker <профиль>|auto] [--contract <файл>] [--class code|design|review|research] [--backlog]\n  {prog} task set <id> [--title] [--lane] [--deps a,b] [--worker <профиль>|auto] [--contract] [--status backlog|ready]\n                [--kind implement|review|research|decision|root]   --kind: только открытая задача (не принятая и не вытесненная)\n                                           --worker: решает пресет — агентам не передавать; воркер вне пресета — отказ (выход 2),\n                                           если это не человек в терминале; auto снимает выбор\n  {prog} verify <id>                         оркестратору: взять законченную работу на проверку (агентам можно)\n  {prog} verify <id> --done --note \"…\"      проверено: гейты, стенд, правки — после этого задача ждёт человека\n  {prog} start <id>                          оркестратору: взять в работу root-задачу (свою работу)\n  {prog} verify <id> --done --note \"…\" [--report <файл>]\n                                           root-задача: сделано, уходит на приёмку; решение: подготовлено (варианты, рекомендация),\n                                           только тогда попадает к человеку; отчёт начинается строкой «Результат:»\n  {prog} verify <id> --return \"замечания\"   вернуть воркеру с замечаниями (новый запуск в той же рабочей копии)\n  {prog} verify --setting on|off|default [--scope plan|repo]\n                                           оркестратор проверяет законченную работу; по умолчанию — если у плана есть чат\n  {prog} accept <id>                         только человек (интерактивный терминал); принятую работу ещё нужно слить —\n                                           зависимые задачи ждут слияния, команды печатаются после приёмки\n  {prog} reject <id> --reason \"…\"            только человек: вернуть с причиной\n  {prog} supersede <id> --by <id>            только человек: вариант проиграл сравнение\n  {prog} drop <id> --reason \"…\"              только человек: закрыть ненужную задачу; в очередь она больше не вернётся\n\nЗапуски\n  {prog} run <id> -a <профиль> [--scope s] [--contract f] [--skip-preflight]\n                                           агенты dsh: -a dsh или -a dsh/<модель> (например dsh/deepseek-flash)\n  {prog} run <id>                            без -a — назначенный воркер задачи; если не задан, порядок пресета для класса\n                                           -a — выбор человека: агентам не передавать, вне пресета — отказ (выход 2);\n                                           нужен другой воркер — спросите человека. -a auto снимает выбор\n  {prog} run <id> --allow-unmerged            только человек: начать, хотя зависимость принята, но не слита —\n                                           в копии этой работы не будет\n  {prog} events <id>\n  {prog} trace <id> [--json]                трассировка: ходы, модель, инструменты, поправки\n  {prog} steer <id> (--message \"…\" | --file f) [--mode auto|queue|interrupt] [--relaunch] [--skip-preflight]\n  {prog} stop <id>\n  {prog} continue <id>                       запуск закончился без отчёта и с незакоммиченной работой:\n                                           новый запуск в той же копии с указанием доделать и отчитаться\n  {prog} attention [--all] [--json] [--alarms]\n                                           что ждёт человека — «Ждут вас» на экране: проверки, решения,\n                                           принятое, но не слитое, упавшие или зависшие запуски, другие планы; --alarms — только тревоги запусков\n  {prog} cost [--json]                       по воркерам: деньги (списано) и оценка (по API-ценам для запусков\n                                           по подписке), не складываются; в JSON: cashUsd, apiEquivalentUsd\n\nВоркеры\n  {prog} workers                             реестр и порядок воркеров по классам задач\n  {prog} workers add <id> --kind … --model … --label … | rm <id>\n  {prog} workers disable <id> --reason \"…\" | enable <id> | route <class> <id,id,…>\n\nОкружение\n  {prog} preflight [-a <профиль>] [--probe] [--json]\n  {prog} worktree prepare <id> [--scope s]\n  {prog} worktree list\n  {prog} worktree gc [--yes]                 без --yes только показывает причины и размеры, ничего не убирает;\n                                           --yes убирает и перечисляет убранное или почему всё осталось\n  {prog} worktree gc --force <id>            --force только человек: убрать копию с изменениями\n",
